1	//! Camera layouts' geometry (road map "creator-jobs" CO6, spec §11 CO-60,
2	//! CO-65): where a layout puts the camera and the screen, as the six
3	//! placement keys `switch_layout` writes on each — `x`, `y`, `scale`,
4	//! `crop`, `corner_radius`, `opacity` — and nothing else. Pure: every
5	//! number is read from the container's canvas and the source sizes.
6	//!
7	//! W × H is the container's canvas (a nest's own inside a scope) and
8	//! `m = MARGIN·min(W, H)`. Every scale is clamped to
9	//! `SCALE_MIN…SCALE_MAX`; `x` and `y` are rounded half away from zero to
10	//! whole canvas pixels, as CAM-10 (3) rounds them; scale, crop and radius
11	//! are not. A radius is written in SOURCE pixels, its canvas length ÷ the
12	//! scale. A crop's centre is placed by `edit_zoom.rs`'s (★): the cropped
13	//! centre is the anchor plus `s·((l − r)/2, (t − b)/2)`.
14	//!
15	//! - **Full placement** is `add_clip`'s: 0, 0, `fit_scale`, no crop,
16	//!   radius 0, opacity 1 — the screen's in `corner`, `camera_full` and
17	//!   `screen_only`.
18	//! - **corner**: the box is `CORNER_WIDTH·W × CORNER_HEIGHT·H`, the
19	//!   picture's outer corner `CORNER_INSET` of each axis in from the chosen
20	//!   canvas corner. `square` and `rounded` fit the whole camera in it
21	//!   (CAM-10 (3)'s `cornerPatch` exactly); `rounded`'s radius is
22	//!   `ROUNDED_RADIUS` of the box's shorter side. `circle` crops the largest
23	//!   square of the source, centred on `focus`, to the box's shorter side,
24	//!   with a radius of half the square's side.
25	//! - **side_by_side**: the screen fitted in the left `SCREEN_SHARE` of the
26	//!   inner width `W − 3m` and `H − 2m` tall, centred there; the camera
27	//!   cropped to fill the right third; `PANEL_RADIUS` of the canvas's
28	//!   shorter side on each.
29	//! - **stacked**: the screen at `min((W − 2m)/sw, (H − 3m)·SCREEN_SHARE/sh)`,
30	//!   centred across, its top at m; the camera cropped to fill the
31	//!   `(W − 2m)`-wide rest below it, m between; the same radii.
32	//! - **camera_full**: the camera at `fill_scale`, uncropped, square.
33	//! - **screen_only**: the camera keeps where it is, at opacity 0.
34	//!
35	//! `focus` (CO-65) is a point in the camera's source pixels from the
36	//! UNCROPPED source's centre, y down; a crop is centred on it and clamped
37	//! inside the source.
38	
39	use serde::{Deserialize, Serialize};
40	use serde_json::{json, Value};
41	
42	use crate::model::{Crop, Project, VideoProps};
43	use crate::props_check::{SCALE_MAX, SCALE_MIN};
44	use crate::time::{Ticks, TIMESCALE};
45	
46	/// The corner box's width, as a fraction of the canvas's (CAM-10 (3)).
47	pub(crate) const CORNER_WIDTH: f64 = 0.25;
48	/// The corner box's height, as a fraction of the canvas's.
49	pub(crate) const CORNER_HEIGHT: f64 = 1.0 / 3.0;
50	/// The corner picture's inset from the canvas's edges, per axis: the 90 %
51	/// ring of View ▸ Safe Areas.
52	pub(crate) const CORNER_INSET: f64 = 0.05;
53	/// `rounded`'s radius, as a fraction of the corner box's shorter side.
54	pub(crate) const ROUNDED_RADIUS: f64 = 0.08;
55	/// The margin round and between the panels, of the canvas's shorter side.
56	pub(crate) const MARGIN: f64 = 0.04;
57	/// Each panel's radius in `side_by_side` and `stacked`, of the canvas's
58	/// shorter side.
59	pub(crate) const PANEL_RADIUS: f64 = 0.02;
60	/// The screen's share of the inner width (`side_by_side`) or height
61	/// (`stacked`).
62	pub(crate) const SCREEN_SHARE: f64 = 2.0 / 3.0;
63	/// A switch's length when `duration` is absent (owner, 2026-11-01).
64	pub(crate) const DEFAULT_SWITCH: Ticks = TIMESCALE / 2;
65	
66	/// The five layouts (CO-60).
67	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
68	#[serde(rename_all = "snake_case")]
69	pub enum CameraLayout {
70	    Corner,
71	    SideBySide,
72	    Stacked,
73	    CameraFull,
74	    ScreenOnly,
75	}
76	
77	impl CameraLayout {
78	    /// Whether the screen takes its full placement in this layout.
79	    pub(crate) fn screen_full(self) -> bool {
80	        matches!(
81	            self,
82	            CameraLayout::Corner | CameraLayout::CameraFull | CameraLayout::ScreenOnly
83	        )
84	    }
85	}
86	
87	/// The corner picture's shape.
88	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
89	#[serde(rename_all = "snake_case")]
90	pub enum LayoutShape {
91	    #[default]
92	    Square,
93	    Rounded,
94	    Circle,
95	}
96	
97	/// The canvas corner the corner picture sits in.
98	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
99	#[serde(rename_all = "snake_case")]
100	pub enum LayoutCorner {
101	    #[default]
102	    BottomRight,
103	    BottomLeft,
104	    TopRight,
105	    TopLeft,
106	}
107	
108	impl LayoutCorner {
109	    /// The signs of the corner's offset from the canvas centre, y down.
110	    fn signs(self) -> (f64, f64) {
111	        match self {
112	            LayoutCorner::BottomRight => (1.0, 1.0),
113	            LayoutCorner::BottomLeft => (-1.0, 1.0),
114	            LayoutCorner::TopRight => (1.0, -1.0),
115	            LayoutCorner::TopLeft => (-1.0, -1.0),
116	        }
117	    }
118	}
119	
120	/// What a switch asks for: the layout, its corner shape and corner, and
121	/// the camera's focus (CO-65).
122	#[derive(Debug, Clone, Copy, PartialEq)]
123	pub(crate) struct LayoutChoice {
124	    pub layout: CameraLayout,
125	    pub shape: LayoutShape,
126	    pub corner: LayoutCorner,
127	    pub focus: (f64, f64),
128	}
129	
130	/// The six placement keys a layout writes on a role.
131	#[derive(Debug, Clone, Copy, PartialEq)]
132	pub(crate) struct Placement {
133	    pub x: f64,
134	    pub y: f64,
135	    pub scale: f64,
136	    pub crop: Crop,
137	    pub corner_radius: f64,
138	    pub opacity: f64,
139	}
140	
141	impl Placement {
142	    /// Exactly the six keys, `crop` as `{l, t, r, b}`: a `set_video` patch,
143	    /// and an action end's `video`.
144	    pub(crate) fn to_json(self) -> Value {
145	        json!({
146	            "x": self.x,
147	            "y": self.y,
148	            "scale": self.scale,
149	            "crop": {"l": self.crop.l, "t": self.crop.t, "r": self.crop.r, "b": self.crop.b},
150	            "corner_radius": self.corner_radius,
151	            "opacity": self.opacity,
152	        })
153	    }
154	
155	    /// The six keys of a video group.
156	    pub(crate) fn of(video: &VideoProps) -> Placement {
157	        Placement {
158	            x: video.x,
159	            y: video.y,
160	            scale: video.scale,
161	            crop: video.crop,
162	            corner_radius: video.corner_radius,
163	            opacity: video.opacity,
164	        }
165	    }
166	
167	    /// The six keys an action's end names in `video`, or `None` when one is
168	    /// missing or not a number.
169	    pub(crate) fn from_end(end: &Value) -> Option<Placement> {
170	        let video = end.get("video")?;
171	        let number = |key: &str| video.get(key).and_then(Value::as_f64);
172	        let crop: Crop = serde_json::from_value(video.get("crop")?.clone()).ok()?;
173	        Some(Placement {
174	            x: number("x")?,
175	            y: number("y")?,
176	            scale: number("scale")?,
177	            crop,
178	            corner_radius: number("corner_radius")?,
179	            opacity: number("opacity")?,
180	        })
181	    }
182	}
183	
184	/// Whether `placed` is `full`: every one of the nine numbers within 1e-9
185	/// (CO-62).
186	pub(crate) fn holds_full(placed: &Placement, full: &Placement) -> bool {
187	    let near = |a: f64, b: f64| (a - b).abs() <= 1e-9;
188	    near(placed.x, full.x)
189	        && near(placed.y, full.y)
190	        && near(placed.scale, full.scale)
191	        && near(placed.crop.l, full.crop.l)
192	        && near(placed.crop.t, full.crop.t)
193	        && near(placed.crop.r, full.crop.r)
194	        && near(placed.crop.b, full.crop.b)
195	        && near(placed.corner_radius, full.corner_radius)
196	        && near(placed.opacity, full.opacity)
197	}
198	
199	/// A scale in the layer's legal range.
200	fn clamp_scale(scale: f64) -> f64 {
201	    if scale.is_finite() {
202	        scale.clamp(SCALE_MIN, SCALE_MAX)
203	    } else {
204	        1.0
205	    }
206	}
207	
208	/// The container's canvas, and its margin.
209	fn canvas(p: &Project) -> (f64, f64, f64) {
210	    let (w, h) = (f64::from(p.canvas.width), f64::from(p.canvas.height));
211	    (w, h, MARGIN * w.min(h))
212	}
213	
214	/// A `cw × ch` crop of an `a × b` source centred on `focus` (from the
215	/// uncropped centre, y down), clamped inside the source.
216	fn centred_crop(source: (f64, f64), size: (f64, f64), focus: (f64, f64)) -> Crop {
217	    let (a, b) = source;
218	    let axis = |whole: f64, part: f64, at: f64| {
219	        let part = if part >= whole - 1e-9 { whole } else { part };
220	        let room = (whole - part) / 2.0;
221	        // `switch_layout` refuses a non-finite focus before it gets here.
222	        let centre = at.clamp(-room, room);
223	        (room + centre, room - centre)
224	    };
225	    let (l, r) = axis(a, size.0, focus.0);
226	    let (t, b) = axis(b, size.1, focus.1);
227	    Crop { l, t, r, b }
228	}
229	
230	/// The `x`, `y` that put a cropped picture's centre at `centre` (an offset
231	/// from the canvas centre) at scale `s` — (★) turned round, rounded.
232	fn place(centre: (f64, f64), scale: f64, crop: &Crop) -> (f64, f64) {
233	    let x = centre.0 - scale * (crop.l - crop.r) / 2.0;
234	    let y = centre.1 - scale * (crop.t - crop.b) / 2.0;
235	    (x.round(), y.round())
236	}
237	
238	/// The camera cropped to fill a `bw × bh` box centred at `centre`.
239	fn filled(
240	    source: (f64, f64),
241	    boxed: (f64, f64),
242	    centre: (f64, f64),
243	    focus: (f64, f64),
244	    radius: f64,
245	) -> Placement {
246	    let (a, b) = source;
247	    let scale = clamp_scale((boxed.0 / a).max(boxed.1 / b));
248	    let crop = centred_crop(source, (boxed.0 / scale, boxed.1 / scale), focus);
249	    let (x, y) = place(centre, scale, &crop);
250	    Placement {
251	        x,
252	        y,
253	        scale,
254	        crop,
255	        corner_radius: radius / scale,
256	        opacity: 1.0,
257	    }
258	}
259	
260	/// `add_clip`'s placement of a source of this size (CO-60).
261	pub(crate) fn full_placement(p: &Project, source: (f64, f64)) -> Placement {
262	    Placement {
263	        x: 0.0,
264	        y: 0.0,
265	        scale: p.fit_scale(source.0, source.1),
266	        crop: Crop::default(),
267	        corner_radius: 0.0,
268	        opacity: 1.0,
269	    }
270	}
271	
272	/// The screen's scale in `stacked`.
273	fn stacked_screen_scale(p: &Project, source: (f64, f64)) -> f64 {
274	    let (w, h, m) = canvas(p);
275	    clamp_scale(((w - 2.0 * m) / source.0).min((h - 3.0 * m) * SCREEN_SHARE / source.1))
276	}
277	
278	/// Where the screen goes in `layout` (CO-60).
279	pub(crate) fn screen_placement(p: &Project, layout: CameraLayout, source: (f64, f64)) -> Placement {
280	    let (w, h, m) = canvas(p);
281	    let radius = PANEL_RADIUS * w.min(h);
282	    match layout {
283	        CameraLayout::SideBySide => {
284	            let bw = (w - 3.0 * m) * SCREEN_SHARE;
285	            let bh = h - 2.0 * m;
286	            let scale = clamp_scale((bw / source.0).min(bh / source.1));
287	            let x = (m + bw / 2.0 - w / 2.0).round();
288	            Placement {
289	                x,
290	                y: 0.0,
291	                scale,
292	                crop: Crop::default(),
293	                corner_radius: radius / scale,
294	                opacity: 1.0,
295	            }
296	        }
297	        CameraLayout::Stacked => {
298	            let scale = stacked_screen_scale(p, source);
299	            let y = (m + source.1 * scale / 2.0 - h / 2.0).round();
300	            Placement {
301	                x: 0.0,
302	                y,
303	                scale,
304	                crop: Crop::default(),
305	                corner_radius: radius / scale,
306	                opacity: 1.0,
307	            }
308	        }
309	        CameraLayout::Corner | CameraLayout::CameraFull | CameraLayout::ScreenOnly => {
310	            full_placement(p, source)
311	        }
312	    }
313	}
314	
315	/// Where the camera goes (CO-60): `screen` is the screen's source size
316	/// (`stacked` stands the camera under it), `kept` the camera's own six keys
317	/// now (`screen_only` keeps them at opacity 0).
318	pub(crate) fn camera_placement(
319	    p: &Project,
320	    choice: &LayoutChoice,
321	    source: (f64, f64),
322	    screen: Option<(f64, f64)>,
323	    kept: &Placement,
324	) -> Placement {
325	    let (w, h, m) = canvas(p);
326	    let panel = PANEL_RADIUS * w.min(h);
327	    let (a, b) = source;
328	    match choice.layout {
329	        CameraLayout::Corner => corner(p, choice, source),
330	        CameraLayout::SideBySide => {
331	            let inner = w - 3.0 * m;
332	            let boxed = (inner * (1.0 - SCREEN_SHARE), h - 2.0 * m);
333	            let left = m + inner * SCREEN_SHARE + m;
334	            let centre = (left + boxed.0 / 2.0 - w / 2.0, 0.0);
335	            filled(source, boxed, centre, choice.focus, panel)
336	        }
337	        CameraLayout::Stacked => {
338	            let above = screen.map_or(0.0, |s| s.1 * stacked_screen_scale(p, s));
339	            let boxed = (w - 2.0 * m, h - 3.0 * m - above);
340	            let centre = (0.0, 2.0 * m + above + boxed.1 / 2.0 - h / 2.0);
341	            filled(source, boxed, centre, choice.focus, panel)
342	        }
343	        CameraLayout::CameraFull => Placement {
344	            x: 0.0,
345	            y: 0.0,
346	            scale: p.fill_scale(a, b),
347	            crop: Crop::default(),
348	            corner_radius: 0.0,
349	            opacity: 1.0,
350	        },
351	        CameraLayout::ScreenOnly => Placement {
352	            opacity: 0.0,
353	            ..*kept
354	        },
355	    }
356	}
357	
358	/// `corner`'s three shapes.
359	fn corner(p: &Project, choice: &LayoutChoice, source: (f64, f64)) -> Placement {
360	    let (w, h, _) = canvas(p);
361	    let (a, b) = source;
362	    let (bw, bh) = (CORNER_WIDTH * w, CORNER_HEIGHT * h);
363	    let (sx, sy) = choice.corner.signs();
364	    let (ix, iy) = (CORNER_INSET * w, CORNER_INSET * h);
365	    match choice.shape {
366	        LayoutShape::Square | LayoutShape::Rounded => {
367	            let scale = clamp_scale((bw / a).min(bh / b));
368	            let x = (sx * (w / 2.0 - ix - a * scale / 2.0)).round();
369	            let y = (sy * (h / 2.0 - iy - b * scale / 2.0)).round();
370	            let corner_radius = match choice.shape {
371	                LayoutShape::Rounded => ROUNDED_RADIUS * bw.min(bh) / scale,
372	                _ => 0.0,
373	            };
374	            Placement {
375	                x,
376	                y,
377	                scale,
378	                crop: Crop::default(),
379	                corner_radius,
380	                opacity: 1.0,
381	            }
382	        }
383	        LayoutShape::Circle => {
384	            let side = a.min(b);
385	            let crop = centred_crop(source, (side, side), choice.focus);
386	            let scale = clamp_scale(bw.min(bh) / side);
387	            let shown = side * scale / 2.0;
388	            let centre = (sx * (w / 2.0 - ix - shown), sy * (h / 2.0 - iy - shown));
389	            let (x, y) = place(centre, scale, &crop);
390	            Placement {
391	                x,
392	                y,
393	                scale,
394	                crop,
395	                corner_radius: side / 2.0,
396	                opacity: 1.0,
397	            }
398	        }
399	    }
400	}
