1	//! `switch_layout` — a camera clip and the screen behind it laid out at the
2	//! playhead (road map "creator-jobs" CO6, spec §11 CO-61, CO-62, CO-64).
3	//! One op, so Clip ▸ Camera Layout ▸ is one undo step, "Camera Layout".
4	//! The geometry is `layout.rs`'s; this file is who is laid out, how far,
5	//! and what refuses.
6	//!
7	//! - **The roles** (CO-64): the camera, playing at `at` with a picture; the
8	//!   screen given (on a track behind) or found — the clip playing at `at`
9	//!   on the front-most visible, non-matte track behind the camera's with a
10	//!   drawn picture. No screen refuses `side_by_side` and `stacked`; the
11	//!   other three lay out the camera alone.
12	//! - **The switch** (CO-61): per role, the clip under `at` gets a LAYOUT
13	//!   ACTION (all six placement keys) at clip time `at − start`, 0.5 s and
14	//!   `ease_in_out` unless told, clamped to the clip and to its next later
15	//!   layout action, at least one frame; at its first frame the layout is
16	//!   its base and a one-frame layout action ends there (a cut). A layout
17	//!   action starting at `at` is replaced; one running at `at` is shortened
18	//!   to end there. The REACH (`edit_layout_reach.rs`) gives every later
19	//!   picture clip on the role's track starting before the next layout
20	//!   action, `through` or the track's end the layout as its base.
21	//! - **The refusals** (CO-62), in order: the camera, the screen, a nest
22	//!   clip asked for a radius it cannot draw, a mover — a non-layout action
23	//!   that moves a role clip and ends after `at` (a full-placement screen
24	//!   exempt in the three layouts that leave it full) — then whatever the
25	//!   composed ops say. `nest: true` nests the moving role's clips first and
26	//!   lays out the nest clip, unless one of them is already laid out.
27	//!
28	//! Composed from `remove_action`, `set_action`, `add_action`,
29	//! `set_action_end`, `set_video` and `nest_clips`, each refusal inherited in
30	//! its own words.
31	
32	use std::collections::HashSet;
33	
34	use serde_json::json;
35	
36	use crate::action_class::is_layout;
37	use crate::edit_adjustment::is_adjustment;
38	use crate::edit_clip::clip_end;
39	use crate::edit_layout_reach::{Role, RoleKind};
40	use crate::layout::{
41	    camera_placement, screen_placement, CameraLayout, LayoutChoice, LayoutCorner, LayoutShape,
42	    Placement, DEFAULT_SWITCH,
43	};
44	use crate::model::{Clip, Curve, Project, Source};
45	use crate::outcome::Outcome;
46	use crate::time::{format_timecode, Ticks};
47	
48	/// `switch_layout`'s arguments, in the op's row order (`edit.rs`).
49	#[derive(Debug, Clone, PartialEq)]
50	pub struct LayoutSwitch {
51	    pub camera: u32,
52	    pub screen: Option<u32>,
53	    pub layout: CameraLayout,
54	    pub shape: Option<LayoutShape>,
55	    pub corner: Option<LayoutCorner>,
56	    pub at: Ticks,
57	    pub duration: Option<Ticks>,
58	    pub curve: Option<Curve>,
59	    pub focus: Option<[f64; 2]>,
60	    pub nest: Option<bool>,
61	    pub through: Option<Ticks>,
62	}
63	
64	/// One role's writes: the clip under `at`, `at` in its clip time, its
65	/// layout action's end, and each later reach clip's new base.
66	type RoleWrites = (u32, Ticks, Placement, Vec<(u32, Placement)>);
67	
68	/// One composed step: the project it applied, unchanged on an identity,
69	/// or the refusal handed straight back.
70	macro_rules! step {
71	    ($next:ident, $call:expr) => {
72	        match $call? {
73	            Outcome::Applied(applied) => $next = applied,
74	            Outcome::Identity => {}
75	            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
76	        }
77	    };
78	}
79	
80	impl Project {
81	    /// Whether `clip` has a picture to lay out: a video group and a source
82	    /// size (CO-64).
83	    pub(crate) fn has_layout_picture(&self, clip: &Clip) -> bool {
84	        clip.video.is_some() && self.source_size(clip).is_some()
85	    }
86	
87	    /// `at` as a timecode, for a sentence.
88	    pub(crate) fn layout_timecode(&self, t: Ticks) -> String {
89	        format_timecode(t, self.canvas.fps, self.canvas.timecode_frames)
90	    }
91	
92	    /// Lays out `s.camera` and its screen at `s.at` (this module's doc).
93	    pub fn switch_layout(&self, s: &LayoutSwitch) -> Result<Outcome, String> {
94	        let at = self.snapped(s.at);
95	        if at < 0 {
96	            return Err(format!("at must not be negative, not {}", s.at));
97	        }
98	        let duration = match s.duration {
99	            None => DEFAULT_SWITCH,
100	            Some(given) => {
101	                let snapped = self.snapped(given);
102	                if snapped <= 0 {
103	                    return Err(format!("duration must be positive, not {given}"));
104	                }
105	                snapped
106	            }
107	        };
108	        let through = match s.through {
109	            None => None,
110	            Some(given) => {
111	                let snapped = self.snapped(given);
112	                if snapped <= at {
113	                    return Err(format!("through must be after at ({at}), not {given}"));
114	                }
115	                Some(snapped)
116	            }
117	        };
118	        let focus = match s.focus {
119	            None => (0.0, 0.0),
120	            Some([x, y]) if x.is_finite() && y.is_finite() => (x, y),
121	            Some([x, y]) => {
122	                return Err(format!("focus must be two finite numbers, not [{x}, {y}]"))
123	            }
124	        };
125	        let choice = LayoutChoice {
126	            layout: s.layout,
127	            shape: s.shape.unwrap_or_default(),
128	            corner: s.corner.unwrap_or_default(),
129	            focus,
130	        };
131	
132	        // The camera (CO-64).
133	        let camera = self.require_clip(s.camera)?;
134	        if let Some(why) = self.role_refusal(camera, at) {
135	            return Ok(Outcome::Refused(why));
136	        }
137	        // The screen, given or found.
138	        let screen = match s.screen {
139	            Some(id) => {
140	                let screen = self.require_clip(id)?;
141	                if let Some(why) = self.role_refusal(screen, at) {
142	                    return Ok(Outcome::Refused(why));
143	                }
144	                let behind = match (
145	                    self.track_index(screen.track),
146	                    self.track_index(camera.track),
147	                ) {
148	                    (Some(back), Some(front)) => back < front,
149	                    _ => false,
150	                };
151	                if !behind {
152	                    return Ok(Outcome::Refused(format!(
153	                        "the screen (clip {}) must be on a track behind the camera's (clip {})",
154	                        screen.id, camera.id
155	                    )));
156	                }
157	                Some(screen)
158	            }
159	            None => self.screen_behind(camera, at),
160	        };
161	        if screen.is_none() && matches!(s.layout, CameraLayout::SideBySide | CameraLayout::Stacked)
162	        {
163	            return Ok(Outcome::Refused(format!(
164	                "no clip draws behind clip {} at {} to be the screen",
165	                camera.id,
166	                self.layout_timecode(at)
167	            )));
168	        }
169	
170	        let mut roles = vec![self.role(RoleKind::Camera, camera, at, through)];
171	        if let Some(screen) = screen {
172	            roles.push(self.role(RoleKind::Screen, screen, at, through));
173	        }
174	        let movers: Vec<Option<String>> = roles
175	            .iter()
176	            .map(|role| self.mover_refusal(role, s.layout))
177	            .collect();
178	        let nesting = s.nest == Some(true);
179	
180	        // A nest clip cannot draw a radius (CO-62).
181	        if s.layout == CameraLayout::Corner && choice.shape != LayoutShape::Square {
182	            let camera_role = &roles[0];
183	            let becomes = nesting && movers[0].is_some();
184	            let nested = camera_role
185	                .clips()
186	                .find(|c| matches!(c.source, Source::Nest { .. }))
187	                .map(|c| c.id)
188	                .or(becomes.then_some(camera_role.clip.id));
189	            if let Some(id) = nested {
190	                return Ok(Outcome::Refused(format!(
191	                    "clip {id} is a nest clip, which cannot draw a rounded corner or a circle."
192	                )));
193	            }
194	        }
195	
196	        // The movers: refused, or nested first.
197	        if !nesting {
198	            if let Some(why) = movers.iter().flatten().next() {
199	                return Ok(Outcome::Refused(why.clone()));
200	            }
201	        } else if movers.iter().any(Option::is_some) {
202	            return self.nest_then_switch(s, &roles, &movers);
203	        }
204	
205	        let curve = s.curve.unwrap_or(Curve::EaseInOut);
206	        self.compose_switch(&choice, &roles, at, duration, curve)
207	    }
208	
209	    /// The switch composed once its refusals have passed (CO-61): every
210	    /// placement solved on the project as it is, then per role the layout
211	    /// action at `at` (replacing one starting there, shortening one running
212	    /// there, a cut at a first frame) and the bases of `later`. Shared by
213	    /// `switch_layout` and `reframe_layout.rs`'s replay (spec §11 VR-53 (b)).
214	    pub(crate) fn compose_switch(
215	        &self,
216	        choice: &LayoutChoice,
217	        roles: &[Role<'_>],
218	        at: Ticks,
219	        duration: Ticks,
220	        curve: Curve,
221	    ) -> Result<Outcome, String> {
222	        // Every placement is solved on the project as it is.
223	        let screen_size = roles
224	            .iter()
225	            .find(|role| role.kind == RoleKind::Screen)
226	            .and_then(|role| self.source_size(role.clip));
227	        let mut writes: Vec<RoleWrites> = Vec::new();
228	        for role in roles {
229	            let solve = |clip: &Clip, kept: Placement| -> Option<Placement> {
230	                let source = self.source_size(clip)?;
231	                Some(match role.kind {
232	                    RoleKind::Camera => camera_placement(self, choice, source, screen_size, &kept),
233	                    RoleKind::Screen => screen_placement(self, choice.layout, source),
234	                })
235	            };
236	            let t = at - role.clip.start;
237	            let kept = Placement::of(&self.evaluate_clip(role.clip, t).video);
238	            let Some(end) = solve(role.clip, kept) else {
239	                continue;
240	            };
241	            let bases = role
242	                .later
243	                .iter()
244	                .filter_map(|c| {
245	                    let base = Placement::of(c.video.as_ref()?);
246	                    solve(c, base).map(|p| (c.id, p))
247	                })
248	                .collect();
249	            writes.push((role.clip.id, t, end, bases));
250	        }
251	
252	        let frame = self.frame();
253	        let mut next = self.clone();
254	        for (id, t, end, bases) in &writes {
255	            let (id, t) = (*id, *t);
256	            let clip = self.require_clip(id)?.clone();
257	            let video = end.to_json();
258	            let patch = json!({ "video": video });
259	            // One starting at `at` is replaced; one running at `at` ends there.
260	            if let Some(found) = clip.actions.iter().find(|a| is_layout(a) && a.start == t) {
261	                step!(next, next.remove_action(id, found.id));
262	            }
263	            if let Some(found) = clip
264	                .actions
265	                .iter()
266	                .find(|a| is_layout(a) && a.start < t && t < a.start.saturating_add(a.duration))
267	            {
268	                step!(
269	                    next,
270	                    next.set_action(id, found.id, None, Some(t - found.start), None)
271	                );
272	            }
273	            if t == 0 {
274	                // A cut: the base, and a one-frame action ending at it.
275	                step!(next, next.set_video(&[id], &video));
276	                let action = next.next_id;
277	                step!(next, next.add_action(id, 0, Some(frame)));
278	                step!(next, next.set_action_end(id, action, &patch, &[], None));
279	            } else {
280	                let mut length = duration.min(clip.duration - t);
281	                if let Some(later) = clip
282	                    .actions
283	                    .iter()
284	                    .filter(|a| is_layout(a) && a.start > t)
285	                    .map(|a| a.start)
286	                    .min()
287	                {
288	                    length = length.min(later - t);
289	                }
290	                let length = length.max(frame);
291	                let action = next.next_id;
292	                step!(next, next.add_action(id, t, Some(length)));
293	                step!(next, next.set_action(id, action, None, None, Some(curve)));
294	                step!(next, next.set_action_end(id, action, &patch, &[], None));
295	            }
296	            for (later, base) in bases {
297	                step!(next, next.set_video(&[*later], &base.to_json()));
298	            }
299	        }
300	        self.finish(next)
301	    }
302	
303	    /// The camera's (or a given screen's) refusal: no picture, or not
304	    /// playing at `at` (CO-64).
305	    fn role_refusal(&self, clip: &Clip, at: Ticks) -> Option<String> {
306	        if !self.has_layout_picture(clip) {
307	            return Some(format!("clip {} has no picture to lay out", clip.id));
308	        }
309	        if !(clip.start <= at && at < clip_end(clip)) {
310	            return Some(format!(
311	                "clip {} does not play at {}",
312	                clip.id,
313	                self.layout_timecode(at)
314	            ));
315	        }
316	        None
317	    }
318	
319	    /// The screen found behind `camera` at `at` (CO-64): the clip playing
320	    /// there on the front-most track behind the camera's that is shown and
321	    /// not a matte track, drawing a picture, not an adjustment clip.
322	    fn screen_behind(&self, camera: &Clip, at: Ticks) -> Option<&Clip> {
323	        let front = self.track_index(camera.track)?;
324	        self.tracks
325	            .get(..front)?
326	            .iter()
327	            .rev()
328	            .filter(|track| !track.hidden && track.matte.is_none())
329	            .find_map(|track| {
330	                self.clips.iter().find(|c| {
331	                    c.track == track.id
332	                        && c.start <= at
333	                        && at < clip_end(c)
334	                        && c.enabled.video
335	                        && !is_adjustment(c)
336	                        && self.has_layout_picture(c)
337	                })
338	            })
339	    }
340	
341	    /// `nest: true` (CO-62): each moving role's clips nested, refused when
342	    /// one is already laid out, then the switch on the nest clips.
343	    fn nest_then_switch(
344	        &self,
345	        s: &LayoutSwitch,
346	        roles: &[Role<'_>],
347	        movers: &[Option<String>],
348	    ) -> Result<Outcome, String> {
349	        let mut again = s.clone();
350	        again.nest = None;
351	        let mut next = self.clone();
352	        for (role, mover) in roles.iter().zip(movers) {
353	            if mover.is_none() {
354	                continue;
355	            }
356	            let nested: Vec<&Clip> = role.nested().collect();
357	            if let Some(id) = nested.iter().find(|c| self.laid_out(c)).map(|c| c.id) {
358	                return Ok(Outcome::Refused(format!(
359	                    "clip {id} is already laid out; a nest would lay it out twice."
360	                )));
361	            }
362	            let ids: Vec<u32> = nested.iter().map(|c| c.id).collect();
363	            let before: HashSet<u32> = next.clips.iter().map(|c| c.id).collect();
364	            step!(next, next.nest_clips(&ids, None));
365	            let made = next
366	                .clips
367	                .iter()
368	                .find(|c| !before.contains(&c.id) && matches!(c.source, Source::Nest { .. }))
369	                .map(|c| c.id);
370	            if let Some(made) = made {
371	                match role.kind {
372	                    RoleKind::Camera => again.camera = made,
373	                    RoleKind::Screen => again.screen = Some(made),
374	                }
375	            }
376	        }
377	        match next.switch_layout(&again)? {
378	            Outcome::Applied(laid) => self.finish(laid),
379	            Outcome::Identity => self.finish(next),
380	            Outcome::Refused(why) => Ok(Outcome::Refused(why)),
381	        }
382	    }
383	}
